body_md:
A frame for a separable Hilbert space $H$ is a sequence $(f_n)_n \subset H$ such that for some $0<A<B,$
\begin{equation}\label{framedef}
A\Arrowvert f \Arrowvert^2 \leq \sum_n  | \langle f , f_n \rangle |^2 \leq B\Arrowvert f \Arrowvert^2, \quad \forall f \in H.
\end{equation}

A subset $S$ of $\mathbb{R}^d$ is said to be uniformly separated if
\begin{equation}
\inf_{x,y \in S, x \neq y} \Arrowvert x-y \Arrowvert_2 >0.\nonumber
\end{equation}

\label{main}
Let $0 \in E \subset \mathbb{R}^d$ be compact such that for all $\lambda > 1$, $ E \subset \mathrm{int}(\lambda E).$  Choose $S=(t_n)_{n \in \mathbb{N}} \subset \mathbb{R}^d$ such that $(f_n)_{n \in \mathbb{N}}$, defined by $f_n(\cdotp) = e^{i \langle \cdotp , t_n \rangle}$, is a frame for $L_2(E)$ with frame operator $S$. Let $\lambda_0 >1$ with $\mathcal{F}^{-1}(g):\mathbb{R}^d \rightarrow \mathbb{R}$, $ \mathcal{F}^{-1}(g) \in C^\infty$ where $\mathcal{F}^{-1}(g)\arrowvert_{E} = 1$ and $\mathcal{F}^{-1}(g)\arrowvert_{(\lambda_0 E)^c}$=0.  If $\lambda \geq \lambda_0$ and $f \in PW_E$, then
\begin{equation}\label{biggie}
f(t) = \frac{1}{\lambda^d}\sum_{k \in \mathbb{N}} \Big( \sum_{n \in \mathbb{N}} B_{kn} f\big( \frac{t_n}{\lambda} \big) \Big) g\big(t-\frac{t_k}{\lambda}\big), \quad t \in \mathbb{R}^d,
\end{equation}
where $B_{kn} = \langle S^{-1}f_n , S^{-1}f_k \rangle_E$.  Convergence of the sum is in $L_2(\mathbb{R}^d)$, hence also uniform.  Further, the map $B:\ell_2(\mathbb{N}) \rightarrow \ell_2(\mathbb{N})$ defined by $(y_k)_{k \in \mathbb{N}} \mapsto \big( \sum_{n \in \mathbb{N}} B_{kn} y_n \big)_{k \in \mathbb{N}}$ is bounded linear, and is an onto isomorphism iff $(f_n)_{n \in \mathbb{N}}$ is a Riesz basis for $L_2(E)$.

\noindent Define $f_{\lambda,n} (\cdotp) = f_n \big( \frac{\cdotp}{\lambda} \big)$.  Note that $(f_{\lambda,n})_n$ is a frame for $L_2(\lambda E)$ with frame operator $S_\lambda.$\\

\noindent Step 1: We show that\\
\begin{equation}\label{first}
f = \sum_{n} f \Big( \frac{t_n}{\lambda} \Big) \mathcal{F}[(S^{-1}_\lambda f_{\lambda, n})\mathcal{F}^{-1}(g)], \quad f \in PW_E.
\end{equation}
\noindent We know $\mathrm{supp}(\mathcal{F}^{-1}(f)) \subset E \subset \lambda E$, so we may work with $\mathcal{F}^{-1}(f)$ via its frame decomposition. We have
\begin{equation}
\mathcal{F}^{-1}(f) = S_\lambda^{-1} S_\lambda (\mathcal{F}^{-1} (f)) = \sum_n \langle \mathcal{F}^{-1}(f) , f_{\lambda,n} \rangle_{\lambda E} S^{-1}_{\lambda} f_{\lambda,n}, \quad \mathrm{on} \quad \lambda E\nonumber.
\end{equation}
This yields
\begin{equation}
\mathcal{F}^{-1}(f) = \sum_n \langle \mathcal{F}^{-1}(f) , f_{\lambda,n} \rangle_{\lambda E} (S^{-1}_{\lambda} f_{\lambda,n})\mathcal{F}^{-1}(g), \quad \mathrm{on} \quad \mathbb{R}^d,\nonumber
\end{equation}
\noindent since $\mathrm{supp}\mathcal{F}(g)\subset \lambda E$.  Taking Fourier transforms we obtain
\begin{equation}\label{second}
 f = \sum_n \langle \mathcal{F}^{-1}(f) , f_{\lambda,n} \rangle_{\lambda E} \mathcal{F}[(S^{-1}_{\lambda} f_{\lambda,n})\mathcal{F}^{-1}(g)], \quad \mathrm{on} \quad \mathbb{R}^d.
\end{equation}
Now 
\begin{eqnarray}
\langle \mathcal{F}^{-1}(f) , f_{\lambda,n} \rangle_{\lambda E}  =  \int_{\lambda E} \mathcal{F}^{-1}(f)(\xi) e^{-i \langle \xi , \frac{t_n}{\lambda} \rangle} d\xi = f \Big( \frac{t_n}{\lambda} \Big)\nonumber
\end{eqnarray}
which, when substituted into equation~(\ref{second}), yields (\ref{first}).\\

\noindent Step 2: We show that\\
\begin{equation}\label{third}
f(\cdotp) = \sum_n f \Big( \frac{t_n}{\lambda} \Big) \Big[ \sum_k \langle S^{-1}_\lambda f_{\lambda,n} , S^{-1}_\lambda f_{\lambda,k} \rangle_{\lambda E} g\big(\cdotp-\frac{t_k}{\lambda}\big) \Big],
\end{equation}
where convergence is in $L_2$.\\

\noindent We compute $\mathcal{F}[(S^{-1}_\lambda f_{\lambda,n})\mathcal{F}^{-1}(g)]$.  For $h \in L_2 (\lambda E)$ we have
\begin{eqnarray}
h = S_\lambda (S_\lambda^{-1} h) = \sum_k \langle S_\lambda^{-1} h , f_{\lambda,k} \rangle_{\lambda E} f_{\lambda,k} = \sum_k \langle  h , S_\lambda^{-1} f_{\lambda,k} \rangle_{\lambda E} f_{\lambda,k}.\nonumber
\end{eqnarray}
Letting $h = S^{-1}_\lambda f_{\lambda,n}$,
\begin{equation}
S^{-1}_\lambda f_{\lambda,n} = \sum_k \langle S^{-1}_\lambda f_{\lambda,n} , S^{-1}_\lambda f_{\lambda,k} \rangle_{\lambda E} f_{\lambda,k}.\nonumber
\end{equation}
This gives
\begin{eqnarray}
\mathcal{F}[(S^{-1}_\lambda f_{\lambda,n})F^{-1}(g)](\cdotp) & = & \sum_k \langle S^{-1}_\lambda f_{\lambda,n} , S^{-1}_\lambda f_{\lambda,k} \rangle_{\lambda E} \mathcal{F}[f_{\lambda,k} \mathcal{F}^{-1}(g)](\cdotp)\nonumber\\
& = & \sum_k \langle S^{-1}_\lambda f_{\lambda,n} , S^{-1}_\lambda f_{\lambda,k} \rangle_{\lambda E} \int_{\lambda E} e^{i \langle \xi , \frac{t_k}{\lambda} \rangle}\mathcal{F}^{-1}(g)(\xi) e^{-i \langle \xi , \cdotp \rangle}d \xi \nonumber \\
& = & \sum_k \langle S^{-1}_\lambda f_{\lambda,n} , S^{-1}_\lambda f_{\lambda,k} \rangle_{\lambda E} \int_{\lambda E} \mathcal{F}^{-1}(g)(\xi) e^{-i\langle \cdotp-\frac{t_k}{\lambda} , \xi \rangle} d \xi\nonumber\\ 
& = & \sum_k \langle S^{-1}_\lambda f_{\lambda,n} , S^{-1}_\lambda f_{\lambda,k} \rangle_{\lambda E} g \big( \cdotp -\frac{t_k}{\lambda} \big)\nonumber,
\end{eqnarray}
so (\ref{third}) follows from (\ref{first}).\\

\noindent Step 3: We show that\\
\begin{equation}
\langle S^{-1}_\lambda f_{\lambda,n} , S^{-1}_\lambda f_{\lambda,k} \rangle_{\lambda E} = \frac{1}{\lambda^d}\langle S^{-1} f_n , S^{-1} f_k \rangle_E, \quad \mathrm{for} \quad n,k \in \mathbb{N}.
\end{equation}

\noindent First we show $ (S^{-1}_\lambda f_{\lambda,n})(\cdotp) = \frac{1}{\lambda^d}(S^{-1} f_n)(\frac{\cdotp}{\lambda})$, or equivalently that $ f_{\lambda,n} = \frac{1}{\lambda^d}S_\lambda \big((S^{-1} f_n)(\frac{\cdotp}{\lambda})\big)$.\\

\noindent We have for any $g \in L_2 (\lambda E),$
\begin{eqnarray}
\langle g , f_{\lambda,k} \rangle_{\lambda E} & = & \int_{\lambda E} g(\xi) e ^{-i \langle \frac{\xi}{\lambda} , t_k \rangle} d \xi =  \lambda^d \int_E g(\lambda x) e ^{-i \langle x , t_k \rangle} d x =\lambda^d \langle g(\lambda(\cdot)) , f_k \rangle_E\nonumber.
\end{eqnarray}
By definition of the frame operator $S_\lambda$,
\begin{equation}
S_{\lambda} g = \sum_{k \in \mathbb{N}} \langle g , f_{\lambda,k} \rangle_{\lambda E} f_{\lambda,k}\nonumber,
\end{equation}
which then becomes
\begin{equation}
S_\lambda g = \lambda^d \sum_k \langle g(\lambda(\cdot)) , f_k \rangle_E f_{\lambda,k}.\nonumber
\end{equation}
Substituting $g = \frac{1}{\lambda^d}(S^{-1} f_n)(\frac{\cdotp}{\lambda})$ into the equation above we obtain 
\begin{eqnarray}
\frac{1}{\lambda^d} S_\lambda \big( (S^{-1} f_n) \big(\frac{\cdot}{\lambda} \big) \big) & = & \sum_k \langle S^{-1} f_n  , f_k \rangle_E f_{\lambda,k} = \big( S(S^{-1} f_n) \big) \big( \frac{\cdot}{\lambda} \big) = f_{\lambda,n}.\nonumber
\end{eqnarray}
We now compute the desired inner product:
\begin{eqnarray}
\langle S^{-1}_\lambda f_{\lambda,n} , S^{-1}_\lambda f_{\lambda,k} \rangle_{\lambda E} & = & \frac{1}{\lambda^{2d}}\int_{\lambda E} (S^{-1}f_n)\big(\frac{x}{\lambda}\big)\overline{(S^{-1}f_k)\big(\frac{x}{\lambda}\big)} dx \nonumber\\
& = &  \frac{\lambda^d}{\lambda^{2d}}\int_E (S^{-1} f_n)(x)\overline{(S^{-1} f_k)(x)} dx =  \frac{1}{\lambda^d}\langle S^{-1} f_n , S^{-1} f_k \rangle_E.\nonumber
\end{eqnarray}

\noindent Note that equation~(\ref{third}) becomes
\begin{equation}\label{fourth}
f(\cdotp) = \frac{1}{\lambda^d}\sum_n f \big( \frac{t_n}{\lambda} \big) \Big[ \sum_k \langle S^{-1} f_n , S^{-1} f_k \rangle g\big(\cdotp-\frac{t_k}{\lambda}\big) \big].
\end{equation}

\noindent Step 4:  The map $V:\ell_2 (\mathbb{N}) \rightarrow \ell_2 (\mathbb{N})$ given by $x=(x_k)_{k \in \mathbb{N}} \mapsto \big( \sum_n B_{kn} x_n \big)_{k \in \mathbb{N}} = Bx$ is bounded linear and self-adjoint.\\

\noindent  Let $(d_k)_{k \in \mathbb{N}}$ be the standard basis for $\ell_2 (\mathbb{N})$, and let $(e_k)_{k \in \mathbb{N}}$ be an orthonormal basis for $L_2(E)$.  Then
\begin{eqnarray}\label{matrixform}
V d_j & = & (B_{kj})_{k\in \mathbb{N}} = \sum_k B_{kj} d_k = \sum_k \langle S^{-1} f_j , S^{-1} f_k \rangle d_k =  \sum_k \langle L^*(S^{-1})^2 L e_j , e_k \rangle d_k,\nonumber
\end{eqnarray}
where $L$ is the preframe operator, i.e., $S =L L^*$.  Define $\phi:\ell^2(\mathbb{N}) \rightarrow L_2(E)$ by $\phi(d_k) = e_k$, $k \in \mathbb{N}$. Clearly $\phi$ is unitary.  It follows that $V = \phi^{-1} L^* (S^{-1})^2 L \phi$, which concludes Step 4.  From here on we identify $V$ with $B$. 
Clearly $B$ is an onto isomorphism iff $L$ and $L^*$ are both onto, i.e., iff the map $L e_n = f_n$ is an onto isomorphism.\\

\noindent Step 5: Verification of equation~(\ref{biggie}).  Recalling Definition \ref{seqdef}, $f_{S/\lambda} = \big( f\big(\frac{t_n}{\lambda}\big) \big)_{n \in \mathbb{N}}$; for each $t \in \mathbb{R}^d$, let $g_\lambda (t) = \big( g\big(t-\frac{t_n}{\lambda}\big) \big)_{n \in \mathbb{N}}$.  Noting that $f\big(\frac{\cdot}{\lambda} \big), g\big(t-\frac{\cdot}{\lambda}  \big) \in L_2 (\lambda E)$, and recalling that $(f_{\lambda,n})_n$ is a frame for $L_2(\lambda E)$, we have 
\begin{equation}
\sum_n \big| f\big( \frac{t_n}{\lambda} \big) \big|^2 = \sum |\langle \mathcal{F}^{-1}(f), f_{\lambda,n}\rangle_{\lambda E}|^2 \leq A_\lambda \Arrowvert \mathcal{F}^{-1}(f) \Arrowvert^2,
\end{equation}
and
\begin{equation}
\sum_n \big| g\big(t- \frac{t_n}{\lambda} \big) \big|^2 = \sum |\langle \mathcal{F}^{-1}\big( g\big(t- \frac{\cdot}{\lambda} \big)\big), f_{\lambda,n}\rangle_{\lambda E}|^2 \leq A_\lambda \Arrowvert \mathcal{F}^{-1}\big( g\big(t- \frac{\cdot}{\lambda} \big)\big) \Arrowvert^2.\nonumber
\end{equation}

\noindent Note that equation~(\ref{fourth}) becomes
\begin{eqnarray}\label{fifth}
f(t) & =  & \frac{1}{\lambda^d}\sum_n f \big( \frac{t_n}{\lambda} \big) \Big[ \sum_k B_{kn} g\big(t-\frac{t_k}{\lambda}\big) \Big]  =  \frac{1}{\lambda^d}\sum_n f \big( \frac{t_n}{\lambda} \big) \overline{\Big[ \sum_k B_{nk} \overline{g\big(t-\frac{t_k}{\lambda}\big)} \Big]}\nonumber\\
& = & \frac{1}{\lambda^d}\sum_n (f_{S/\lambda})_n (B\overline{g_\lambda (t)})_n =  \frac{1}{\lambda^d}\langle f_{S/\lambda} , B\overline{g_\lambda (t)} \rangle =  \frac{1}{\lambda^d} \langle B f_{S/\lambda} , \overline{g_\lambda (t)} \rangle\nonumber\\ & = & \frac{1}{\lambda^d}\sum_k (B f_{S/\lambda})_k g\big(t-\frac{t_k}{\lambda}\big) =  \frac{1}{\lambda^d}\sum_{k \in \mathbb{N}} \Big( \sum_{n \in \mathbb{N}} B_{kn} f\big( \frac{t_n}{\lambda} \big) \Big)\nonumber g\big(t-\frac{t_k}{\lambda}\big),
\end{eqnarray}
which proves (\ref{biggie}).\\


\noindent Step 6: We verify that convergence in equation~(\ref{biggie}) is in $L_2 (\mathbb{R})$ (hence uniform).  Define
\begin{equation}
f_n (t) = \frac{1}{\lambda^d}\sum_{1 \leq k \leq n} (B f_{S/\lambda})_k g\big(t-\frac{t_k}{\lambda}\big)\nonumber
\end{equation}
and
\begin{equation}
f_{m,n} (t) = \frac{1}{\lambda^d}\sum_{m \leq k \leq n} (B f_{S/\lambda})_k g\big(t-\frac{t_k}{\lambda}\big).\nonumber
\end{equation}
Then
\begin{eqnarray}
[\mathcal{F}^{-1}(f_{m,n})](\xi) & =  & \frac{1}{\lambda^d} \sum_{m \leq k \leq n} (B f_{S/\lambda})_k \mathcal{F}^{-1}\big[g\big(\cdotp-\frac{t_n}{\lambda} \big)  \big] \nonumber\\
& = & \frac{1}{\lambda^d} \sum_{m \leq k \leq n} (B f_{S/\lambda})_k \mathcal{F}^{-1}(g) (\xi) e^{i \langle \xi , \frac{t_k}{\lambda} \rangle},\nonumber
\end{eqnarray}
so
\begin{eqnarray}
\Arrowvert [\mathcal{F}^{-1}(f_{m,n})] \Arrowvert^2_2 & = & \frac{1}{\lambda^d} \int_{\lambda E} | \mathcal{F}^{-1}(g) (\xi)|^2 \Big| \sum_{m \leq k \leq n} (B f_{S/\lambda})_k e^{i \langle \xi , \frac{t_k}{\lambda} \rangle} \Big|^2 d \xi\nonumber\\
& \leq & \frac{1}{\lambda^d} \Big\Arrowvert \sum_{m \leq k \leq n}  (B f_{S/\lambda})_k f_{\lambda,k} \Big\Arrowvert^2_2.\nonumber
\end{eqnarray}
If $(h_n)_n$ is a orthonormal basis for $L_2(\lambda E)$, then the map $T h_k = f_{\lambda,k}$ (the preframe operator) is bounded linear, so
\begin{eqnarray}
\Arrowvert [\mathcal{F}^{-1}(f_{m,n})] \Arrowvert^2_2 & \leq & \frac{1}{\lambda^d} \Big\Arrowvert T \Big( \sum_{m \leq k \leq n} (B f_{S/\lambda})_k h_k \Big) \Big\Arrowvert^2_2 \leq  \frac{1}{\lambda^d} \Arrowvert T \Arrowvert^2 \sum_{m \leq k \leq n} | (B f_{S/\lambda})_k|^2.\nonumber
\end{eqnarray}
But $B f_{S/\lambda} \in \ell^2(\mathbb{N})$, so $\Arrowvert [\mathcal{F}^{-1}(f_{m,n})] \Arrowvert_2\rightarrow 0$ as $m,n \rightarrow \infty$.   As $\mathcal{F}^{-1}$ is an onto isomorphism, we have $\Arrowvert f_{m,n} \Arrowvert \rightarrow 0$, implying that $\Arrowvert f-f_n \Arrowvert \rightarrow 0$ as $n \rightarrow \infty$.

\label{hmm}
Choose $(t_n)_{n \in \mathbb{N}} \subset \mathbb{R}^d$ such that $(f_n)_{n \in \mathbb{N}}$, defined by $f_n(\cdotp) = \frac{1}{(2\pi)^{d/2}}e^{i \langle \cdotp , t_n \rangle}$, is a frame for $L_2([-\pi,\pi]^d)$.  If $f \in PW_E$, then
\begin{equation}\label{nonoversampling}
f(t) = \sum_{k \in \mathbb{N}} \Big( \sum_{n \in \mathbb{N}} B_{kn} f(t_n) \Big) \mathrm{SINC}(\pi(t-t_k)), \quad t \in \mathbb{R}^d.
\end{equation}
The matrix $B$ and the convergence of the sum are as in Theorem~\ref{main}.

Let $\Lambda \subset \mathbb{R}^d$ be countable such that
\begin{eqnarray}
r(\Lambda) & :=  & \frac{1}{2}\inf_{\lambda, \mu \in  \Lambda, \lambda \neq \mu} \Arrowvert \lambda - \mu \Arrowvert_2 >0\nonumber \\
\mathrm{and} \quad R(\Lambda) & := & \sup_{\xi \in \mathbb{R}^d} \inf_{\lambda \in \Lambda} \Arrowvert \lambda - \mu \Arrowvert_2 < \frac{\pi}{2}.\nonumber
\end{eqnarray}
If $E$ is a subset of the closed unit ball in $\mathbb{R}^d$ and $E$ has positive measure, then $\{e^{i\langle \cdot , \lambda \rangle} | \lambda \in \Lambda\}$ is a frame for $L_2(E)$.

\label{main2}
Let $(n_k)_{k \in \mathbb{N}}$ be an enumeration of $\mathbb{Z}^d$, and $S=(t_k)_{k \in \mathbb{N}} \subset \mathbb{R}^d$ such that $$\lim_{k \rightarrow \infty} \Arrowvert n_k - t_k \Arrowvert_\infty = 0.$$  Define $e_k,f_k:\mathbb{R}^d \rightarrow \mathbb{C}$ by $e_k (x) = \frac{1}{(2\pi)^{d/2}} e^{i \langle n_k , x \rangle}$ and $\frac{1}{(2\pi)^{d/2}} e^{i \langle t_k , x \rangle}$, and let $(h_k)_k$ be the standard basis for $\ell_2(\mathbb{N})$.  Let $P_l:\ell_2(\mathbb{N}) \rightarrow \ell_2(\mathbb{N})$ be the orthogonal projection onto $\mathrm{span}\{h_1,\cdots,h_l\}$.  If $(f_k)_{k \in \mathbb{N}}$ is a Riesz basis for $L_2[-\pi,\pi]^d$, then for all $f \in PW_{[-\pi,\pi]^d}$, we have
\begin{equation}\label{truncatedequation}
f(t) = \lim_{l \rightarrow \infty} \frac{1}{\lambda^d}\sum_{k=1}^l [(P_l B^{-1} P_l)^{-1} f_{S/\lambda}]_k g\big( t-\frac{t_k}{\lambda} \big), \quad t \in \mathbb{R}^d, 
\end{equation}
where convergence is in $L_2$ and uniform.  Furthermore,
\begin{displaymath}
   (P_l B^{-1} P_l)_{nm} = \left\{
     \begin{array}{lr}
       \mathrm{sinc} \pi(t_{n,1}-t_{m,1}) \cdot \ldots \cdot \mathrm{sinc} \pi(t_{n,d}-t_{m,d}),  &  1 \leq n,m \leq l\\
       0, &  \mathrm{otherwise.}
     \end{array}
   \right.
\end{displaymath} 
Convergence of the sum is in $L_2$ and also uniform.

\label{main3}
Under the hypotheses of Theorem \ref{main2},
\begin{equation}
f(t) = \lim_{l \rightarrow \infty}\sum_{k=1}^l [(P_l B^{-1} P_l)^{-1} f_S]_k \mathrm{SINC}( t-t_k), \quad t \in \mathbb{R}^d,
\end{equation}
where convergence of the sum is both $L_2$ and uniform.

\label{finiteversion}
Let $(n_k)_{k \in \mathbb{N}}$ be an enumeration of $\mathbb{Z}^d$, and let $(t_k)_{k \in \mathbb{N}} \subset \mathbb{R}^d$.  Define $e_k,f_k:\mathbb{R}^d \rightarrow \mathbb{C}$ by $e_k (x) = \frac{1}{(2\pi)^{d/2}} e^{i \langle n_k , x \rangle}$ and $f_k(x) = \frac{1}{(2\pi)^{d/2}} e^{i \langle t_k , x \rangle}$. Then for any $r,s\geq 1$, and any finite sequence $(a_k)_{k=r}^s$, we have
\begin{equation}\label{norm}
\Bigg\Arrowvert \sum_{k=r}^s\Big( \frac{a_k}{(2\pi)^{d/2}}e^{i\langle (\cdot) , n_k \rangle}- \frac{a_k}{(2\pi)^{d/2}}e^{i\langle (\cdot) , t_k \rangle} \Big) \Bigg\Arrowvert_2 \leq \Big( e^{\pi d \big({\sup \atop {r \leq k \leq s}} \Arrowvert n_k-t_k \Arrowvert_\infty\big)}-1\Big) \Big(\sum_{k=r}^s |a_k|^2\Big)^{1/2}.
\end{equation}

Let $\delta_k = t_k-n_k$ where $\delta_k = (\delta_{k1}, \cdots , \delta_{kd})$.  Then
\begin{eqnarray}\label{blork}
\phi_{r,s}(x):=\sum_{k=r}^s \frac{a_k}{(2\pi)^{d/2}} \big[ e^{i\langle n_k , x \rangle} - e^{i\langle t_k , x \rangle}\big]
 =  \sum_{k=r}^s \frac{a_k}{(2\pi)^{d/2}}e^{i\langle n_k , x \rangle} \big[ 1 - e^{i\langle \delta_k , x \rangle}\big],
\end{eqnarray}
Now for any $\delta_k$,
\begin{eqnarray}
1 - e^{i \langle \delta_k , x \rangle} & = & 1-e^{i\delta_{k1} x_1} \cdot \ldots \cdot e^{i\delta_{kd} x_d} =  1-\Big(\sum_{j_1 = 0}^{\infty} \frac{(i \delta_{k1} x_1)^{j_1}}{j_1 !}  \Big) \cdot \ldots \cdot \Big( \sum_{j_d = 0}^{\infty} \frac{(i \delta_{kd} x_d)^{j_d}}{j_d !} \Big)\nonumber\\
& = & 1-\sum_{(j_1,\cdots, j_d) \atop j_i \geq 0} \frac{(i \delta_{k1} x_1)^{j_1} \cdot \ldots \cdot (i \delta_{kd} x_d)^{j_d}}{j_1 ! \cdot \ldots \cdot j_d !}\nonumber\\
& = & -\sum_{(j_1,\cdots, j_d) \in J} i^{j_1 +\ldots + j_d}\frac{(\delta_{k1} x_1)^{j_1} \cdot \ldots \cdot (\delta_{kd} x_d)^{j_d}}{j_1 ! \cdot \ldots \cdot j_d !},\nonumber
\end{eqnarray}
where $J = \{ (j_1,\cdots, j_d) \in \mathbb{Z}^d |j_i \geq 0, (j_1,\cdots, j_d) \neq 0\}$.  Then equation~(\ref{blork}) becomes
\begin{eqnarray}
\phi_{r,s}(x) & = & -\sum_{k=r}^s \frac{a_k}{(2\pi)^{d/2}}e^{i\langle n_k , x \rangle}\Big[ \sum_{(j_1,\cdots, j_d) \in J} i^{j_1 +\ldots + j_d}\frac{(\delta_{k1} x_1)^{j_1} \cdot \ldots \cdot (\delta_{kd} x_d)^{j_d}}{j_1 ! \cdot \ldots \cdot j_d !} \Big]\nonumber\\
& = & -\sum_{(j_1,\cdots, j_d) \in J} \frac{x_1^{j_1} \cdot \ldots \cdot x_d^{j_d}}{j_1 ! \cdot \ldots \cdot j_d !} i^{j_1 +\ldots + j_d} \sum_{k=r}^s\frac{a_k}{(2\pi)^{d/2}}\delta_{k1}^{j_1}  \cdot \ldots \cdot \delta_{kd}^{j_d} e^{i \langle n_k , x \rangle},\nonumber
\end{eqnarray}
so
\begin{eqnarray}
|\phi_{r,s}(x)| \leq \sum_{(j_1,\cdots, j_d) \in J} \frac{\pi^{j_1 + \ldots +j_d}}{j_1 ! \cdot \ldots \cdot j_d !} \Big| \sum_{k=r}^s a_k \delta_{k1}^{j_1}  \cdot \ldots \cdot \delta_{kd}^{j_d} \frac{e^{i \langle n_k , x \rangle}}{(2\pi)^{d/2}} \Big|.\nonumber
\end{eqnarray}
For brevity denote the outer summand above by $h_{j_1 , \ldots ,j_d}(t)$.  Then
\begin{eqnarray}
\bigg(\int_{[-\pi,\pi]^d} |\phi_{r,s}(x)|^2 dt \bigg)^\frac{1}{2} & \leq & \bigg( \int_{[-\pi,\pi]^d} \Big| \sum_{(j_1,\cdots, j_d) \in J } h_{j_1 , \ldots ,j_d}(x) \Big|^2 dx \bigg)^\frac{1}{2} \nonumber\\
& \leq & \sum_{(j_1,\cdots, j_d) \in J } \bigg( \int_{[-\pi,\pi]^d} \Big| h_{j_1 , \ldots ,j_d}(x) \Big|^2 dx \bigg)^\frac{1}{2},\nonumber
\end{eqnarray}
so that
\begin{eqnarray}
\Arrowvert \phi_{r,s} \Arrowvert_2 & \leq & \sum_{(j_1,\cdots, j_d) \in J } \frac{\pi^{j_1 + \cdot \ldots \cdot +j_d}}{j_1 ! \cdot \ldots \cdot j_d !} \Big( \int_{[-\pi,\pi]^d} \bigg| \sum_{k=r}^s a_k \delta_{k1}^{j_1}  \cdot \ldots \cdot \delta_{kd}^{j_d} \frac{e^{i \langle n_k , x \rangle}}{(2\pi)^{d/2}} \bigg|^2 dx \Big)^\frac{1}{2}\nonumber\\
& = & \sum_{(j_1,\cdots, j_d) \in J }  \frac{\pi^{j_1 + \cdot \ldots \cdot +j_d}}{j_1 ! \cdot \ldots \cdot j_d !} \Big( \sum_{k=r}^s |a_k|^2 |\delta_{k1}^{j_1}|^2 \cdot \ldots \cdot |\delta_{kd}^{j_d}|^2 \Big)^\frac{1}{2}\nonumber\\
& \leq & \sum_{(j_1,\cdots, j_d) \in J }  \frac{\pi^{j_1 + \cdot \ldots \cdot +j_d}}{j_1 ! \cdot \ldots \cdot j_d !} \Bigg( \sum_{k=r}^s |a_k|^2 \Big({\sup \atop {r \leq k \leq s}} \Arrowvert n_k-t_k \Arrowvert_\infty\Big)^{2(j_1 + \ldots + j_d)} \Bigg)^\frac{1}{2}\nonumber\\
& = & \sum_{(j_1,\cdots, j_d) \in J }  \frac{\Big(\pi{\sup \atop {r \leq k \leq s}} \Arrowvert n_k-t_k \Arrowvert_\infty\Big)^{j_1 + \cdot \ldots \cdot + j_d}}{j_1 ! \cdot \ldots \cdot j_d !} \Big( \sum_{k=r}^s |a_k|^2 \Big)^\frac{1}{2}\nonumber\\
& = & \bigg[ \prod_{l=1}^d\bigg( \sum_{j_\ell = 0}^{\infty} \frac{\big(\pi{\sup \atop {r \leq k \leq s}} \Arrowvert n_k-t_k \Arrowvert_\infty\big)^{j_\ell}}{j_\ell !} \bigg)-1 \bigg]\Big(\sum_{k=r}^s |a_k|^2\Big)^\frac{1}{2}\nonumber\\
& = & \Big( e^{\pi d \big({\sup \atop {r \leq k \leq s}} \Arrowvert n_k-t_k \Arrowvert_\infty\big)}-1\Big) \Big(\sum_{k=r}^s |a_k|^2\Big)^{\frac{1}{2}}.\nonumber
\end{eqnarray}

\label{estimate}
Let $(n_k)_{k \in \mathbb{N}}$ be an enumeration of $\mathbb{Z}^d$, and let $(t_k)_{k \in \mathbb{N}} \subset \mathbb{R}^d$ such that $$\sup_{k \in \mathbb{N}} \Arrowvert n_k - t_k \Arrowvert_\infty = L < \infty.$$  Define $e_k,f_k:\mathbb{R}^d \rightarrow \mathbb{C}$ by $e_k (x) = \frac{1}{(2\pi)^{d/2}} e^{i \langle n_k , x \rangle}$ and $\frac{1}{(2\pi)^{d/2}} e^{i \langle t_k , x \rangle}$.  Then the map $T:L_2[-\pi,\pi]^d \rightarrow L_2[-\pi,\pi]^d$, defined by $T e_n = e_n - f_n$, satisfies the following estimate:
\begin{equation}\label{norm2}
\Arrowvert T \Arrowvert \leq e^{\pi L d} -1.
\end{equation}

As
\begin{eqnarray}
(T-T_l) \big( \sum_{k=1}^\infty a_k e_k \big) & = & \sum_{k=1}^\infty a_k (e_k -f_k) - \sum_{k=1}^l a_k (e_k -f_k) \nonumber\\ 
& = & \sum_{k=l+1}^\infty a_k (e_k -f_k) = T \big( \sum_{k=l+1}^\infty a_k e_k \big),\nonumber
\end{eqnarray}
the estimate derived in lemma (\ref{finiteversion}) yields
\begin{eqnarray}
\big\Arrowvert (T-T_l)\big( \sum_{k=1}^\infty a_k e_k \big) \big\Arrowvert_2 & = & \big\Arrowvert T \big( \sum_{k=l+1}^\infty a_k e_k \big) \big\Arrowvert_2 \leq  \big( e^{\pi d {\sup \atop k \geq l+1} \Arrowvert \delta_k \Arrowvert_\infty}-1 \big) \big\Arrowvert \sum_{k=1}^\infty a_k e_k \big\Arrowvert_2,\nonumber
\end{eqnarray}
so $\big\Arrowvert (T-T_l)\big\Arrowvert_2 \rightarrow 0$ as $l \rightarrow \infty$. As $T_l$ has finite rank, we deduce that $T$ is compact.

\noindent Step 1:  $B$ is a compact perturbation of the identity map, namely
\begin{equation}\label{comppert}
B =  I+\lim_{l \rightarrow \infty} (-P_l +(P_l B^{-1} P_l)^{-1}).
\end{equation}

\noindent Since $(f_k)_{k \in \mathbb{N}}$ is a Riesz basis for $L_2[-\pi,\pi]^d$, $L^* = (I-T)$ is an onto isomorphism where $T e_k = e_k -f_k$; so $B$ simplifies to $(I-T)^{-1} (I-T^*)^{-1}$.  We examine 
\begin{eqnarray}
B^{-1} = (I-T^*)(I-T) = I+(T^* T-T-T^*) := I+\Delta,\nonumber
\end{eqnarray}
where $\Delta$ is a compact operator.  If an operator $\Delta:H \rightarrow H$ is compact then so is $\Delta^*$, hence $P_l \Delta P_l \rightarrow \Delta$ in the operator norm because
\begin{eqnarray}
\Arrowvert P_l \Delta P_l -\Delta  \Arrowvert & \leq & \Arrowvert P_l \Delta P_l -P_l \Delta \Arrowvert + \Arrowvert P_l \Delta -\Delta \Arrowvert \leq  \Arrowvert \Delta P_l -\Delta \Arrowvert + \Arrowvert P_l \Delta -\Delta \Arrowvert\nonumber\\ & = & \Arrowvert  P_l \Delta^* -\Delta^* \Arrowvert + \Arrowvert P_l \Delta -\Delta \Arrowvert \rightarrow 0.\nonumber
\end{eqnarray}
We have
\begin{eqnarray}
B^{-1} & = & \lim_{l \rightarrow \infty} (I+P_l \Delta P_l) =  \lim_{l \rightarrow \infty} (I+P_l (B^{-1}-I) P_l) =  \lim_{l \rightarrow \infty} (I-P_l +P_l B^{-1} P_l).\nonumber
\end{eqnarray}
Now $(P_l B^{-1} P_l)$ restricted to the first $l$ rows and columns is the Grammian matrix for the set $(f_1,\cdots,f_l)$ which can be shown (in a straightforward manner) to be linearly independent. We conclude that $P_l B^{-1} P_l$ is invertible as an $l \times l$ matrix.  By $(P_l B^{-1} P_l)^{-1}$ we mean the inverse as an $l \times l$ matrix and zeroes elsewhere.  Observing that the ranges of $P_l B^{-1} P_l$ and $(P_l B^{-1} P_l)^{-1}$ are in the kernel of $I-P_l$, and that the range of $I-P_l$ is in the kernels of $P_l B^{-1} P_l$ and $(P_l B^{-1} P_l)^{-1}$, we easily compute
\begin{equation}
(I-P_l +(P_l B^{-1} P_l)^{-1})^{-1} = I-P_l +P_l B^{-1} P_l,\nonumber
\end{equation}
so that 
\begin{equation}
B^{-1} = \lim_{l \rightarrow \infty} (I-P_l +(P_l B^{-1} P_l)^{-1})^{-1},\nonumber
\end{equation}
implying
\begin{eqnarray}
B & = & \lim_{l \rightarrow \infty} (I-P_l +(P_l B^{-1} P_l)^{-1}) := \lim_{l \rightarrow \infty} B_l =  I+\lim_{l \rightarrow \infty} (-P_l +(P_l B^{-1} P_l)^{-1}).\nonumber
\end{eqnarray}

\noindent Step 2: We verifiy equation~(\ref{truncatedequation}) and its convergence properties. Recalling equation~(\ref{convenient}), we have
\begin{eqnarray}
f(t) & - & \frac{1}{\lambda^d} \sum_{k=1}^{\infty}[(I-P_l +(P_l B^{-1} P_l)^{-1}) f_{S/\lambda}]_k g\big( t- \frac{t_k}{\lambda} \big) = \frac{1}{\lambda^d} \sum_{k=1}^{\infty}[(B-B_l) f_{S/\lambda}]_k g\big( t- \frac{t_k}{\lambda} \big)\nonumber
\end{eqnarray}
implying
\begin{eqnarray}
f(t) & - & \frac{1}{\lambda^d} \sum_{k=1}^{l}[(P_l B^{-1} P_l)^{-1} f_{S/\lambda}]_k g\big( t- \frac{t_k}{\lambda} \big) \nonumber\\ & = & \frac{1}{\lambda^d} \sum_{k=1}^{\infty}[(B-B_l) f_{S/\lambda}]_k g\big( t- \frac{t_k}{\lambda} \big) + \frac{1}{\lambda^d}\sum_{k=l+1}^{\infty} f\big( \frac{t_k}{\lambda} \big) g\big( t- \frac{t_k}{\lambda} \big).\nonumber
\end{eqnarray}
Therefore,
\begin{eqnarray}
& \Big\Arrowvert & f(\cdot) - \frac{1}{\lambda^d} \sum_{k=1}^{l}[(P_l B^{-1} P_l)^{-1} f_{S/\lambda}]_k g\big( \cdot- \frac{t_k}{\lambda} \big) \Big\Arrowvert_2 = \nonumber\\
& = & \Big\Arrowvert \frac{1}{\lambda^d} \sum_{k=1}^{\infty}[(B-B_l) f_{S/\lambda}]_k g\big( \cdot- \frac{t_k}{\lambda} \big) + \frac{1}{\lambda^d} \sum_{k=l+1}^{\infty} f\big( \frac{t_k}{\lambda} \big) g\big( \cdot- \frac{t_k}{\lambda} \big) \Big\Arrowvert_{[-\lambda\pi,\lambda\pi]^d} \nonumber\\
& = & \frac{1}{\lambda^d} \Big\Arrowvert \mathcal{F}^{-1}(g)(\cdot) \Big( \sum_{k=1}^{\infty}[(B-B_l) f_{S/\lambda}]_k e^{i\langle \cdot , \frac{t_k}{\lambda} \rangle} + \sum_{k=l+1}^{\infty} f\big( \frac{t_k}{\lambda} \big) e^{i\langle \cdot , \frac{t_k}{\lambda} \rangle} \Big) \Big\Arrowvert_{[-\lambda\pi,\lambda\pi]^d}\nonumber
\end{eqnarray}
after taking the inverse Fourier transform.  Now
\begin{eqnarray}
& \Big\Arrowvert & f(\cdot) - \frac{1}{\lambda^d} \sum_{k=1}^{l}[(P_l B^{-1} P_l)^{-1} f_{S/\lambda}]_k g\big( \cdot- \frac{t_k}{\lambda} \big) \Big\Arrowvert_2 \nonumber\\
& \leq & \frac{1}{\lambda^d} \Big\Arrowvert \sum_{k=1}^{\infty}[(B-B_l) f_{S/\lambda}]_k e^{i\langle \cdot , \frac{t_k}{\lambda} \rangle} \Big\Arrowvert_{[-\lambda\pi,\lambda\pi]^d} + \frac{1}{\lambda^d} \Big\Arrowvert \sum_{k=l+1}^{\infty} f\big( \frac{t_k}{\lambda} \big) e^{i\langle \cdot , \frac{t_k}{\lambda} \rangle} \Big\Arrowvert_{[-\lambda\pi,\lambda\pi]^d}\nonumber\\
& \leq & \frac{M}{\lambda^d} \Big\Arrowvert (B-B_l)f_{S/\lambda} \Big\Arrowvert_{\ell_2(\mathbb{N})} + \frac{M}{\lambda^d} \Big( \sum_{k=l+1}^{\infty} \big| f\big( \frac{t_k}{\lambda} \big)  \big|^2 \Big)^\frac{1}{2},\nonumber
\end{eqnarray}
since  $\big(f_k\big(\frac{\cdot}{\lambda}\big)\big)_k$ is a Riesz basis for $L_2[-\lambda\pi, \lambda\pi]^d$.  Since $B_l \rightarrow B$ as $l \rightarrow \infty$ and $\big( f\big(\frac{t_k}{\lambda}\big) \big)_k \in \ell_2(\mathbb{N})$, the last two terms in the inequality above tend to zero, which proves the required result.\\

\noindent Finally, to compute $(P_l B^{-1} P_l)_{nm}$,  recall that $B^{-1} = (I-T^*)(I-T)$.  Proceeding in a manner similar to the proof of equation~(\ref{matrixform}), we obtain
\begin{eqnarray}
B^{-1}_{mn} & = & \langle L L^* e_n , e_m \rangle = \langle L^* e_n ,L^* e_m \rangle = \langle f_n , f_m \rangle\nonumber\\
& = & \mathrm{sinc} \pi(t_{n,1}-t_{m,1}) \cdot \ldots \cdot \mathrm{sinc} \pi(t_{n,d}-t_{m,d}).\nonumber
\end{eqnarray}
The entries of $P_l B^{-1} P_l$ agree with those of $B^{-1}$ when $1 \leq n,m \leq l$.

\label{kadeclike}
Let $(n_k)_{k \in \mathbb{N}}$ be an enumeration of $\mathbb{Z}^d$, and let $(t_k)_{k \in \mathbb{N}} \subset \mathbb{R}^d$ such that
\begin{equation}\label{ineq}
\sup_{k \in \mathbb{N}} \Arrowvert n_k - t_k \Arrowvert_\infty = L < \frac{\ln(2)}{\pi d}.
\end{equation}
Then the sequence $(f_k)_{k \in \mathbb{N}}$ defined by $f_k (x) = \frac{1}{(2\pi)^{d/2}}e^{i \langle x , t_k \rangle}$ is a Riesz basis for $L_2[-\pi,\pi]^d$.

\label{levinsonlike}
Let $(t_n)_{n \in \mathbb{Z}}\subset \mathbb{R}$ be a sequence (with $t_n \neq 0$ for $n \neq 0$) such that $ (f_n)_n = \big(\frac{1}{\sqrt{2\pi}} e^{i t_n (\cdot)} \big)_n$ is a Riesz basis for $L_2[-\pi,\pi]$, and let $(e_n)_n$ be the standard exponential orthonormal basis for $L_2[-\pi,\pi]$.  If the map $L$ given by $L e_n = f_n$ satisfies the estimate $\Arrowvert I-L \Arrowvert<1,$ then the biorthogonals $G_n$ of $\frac{1}{\sqrt{2\pi}}\mathcal{F}(f_n)(\cdot) = \mathrm{sinc}(\pi(\cdot-t_n))$ in $PW_{[-\pi,\pi]}$ are
\begin{equation}
G_n (t) = \frac{H(t)}{(t-t_n)H^{'}(t_n)}, \quad n \in \mathbb{Z},
\end{equation}
where
\begin{equation}\label{holomorphic}
H(t) = (t-t_0) \prod_{n=1}^{\infty} \Big(1-\frac{t}{t_n} \Big) \Big(1-\frac{t}{t_{-n}} \Big).
\end{equation}

If $(c_n)_n \in \ell_2 (\mathbb{Z})$, then
\begin{eqnarray}
(I-L_l)\big(\sum_n c_n e_n \big) & = & \sum_n c_n (e_n-L_l e_n)  = \sum_{|n|\leq l} (e_n -f_n)
= (I-L) P_l \big(\sum_n c_n e_n \big)\nonumber,
\end{eqnarray}
so that
\begin{equation}\label{asdfg}
(I-L_l) = (I-L)P_l.
\end{equation}
From this, $\Arrowvert I-L_l \Arrowvert \leq \delta$, which implies 1) and 2).

Note that
\begin{eqnarray}
\delta_{nm} = \langle f_{l,n} , f_{l,m}^* \rangle = \langle L_l e_n , f_{l,m}^* \rangle = \langle e_n , L_l^* f_{l,m}^*  \rangle\nonumber
\end{eqnarray}
so that for all $m$, $f_{l,m}^* = (L_l^*)^{-1}e_m$.  Similarly, $f_m^* = (L^*)^{-1}e_m$.  We have
\begin{eqnarray}
f_{l,m}^* - f_m^* &=& ((L_l^*)^{-1}-(L^*)^{-1})e_m = (L_l^*)^{-1}(L^*-L_l^*)(L^*)^{-1}e_m.\nonumber
\end{eqnarray}
Now equation (\ref{asdfg}) implies $L-L_l = (L-I)(I-P_l)$, so that
\begin{eqnarray}
f_{l,m}^* - f_m^*  = (L_l^*)^{-1}(I-P_l)(L^*-I)(L^*)^{-1}e_m\nonumber.
\end{eqnarray}
Applying proposition \ref{asdf} yields
\begin{eqnarray}
\Arrowvert f_{l,m}^* - f_m^* \Arrowvert \leq \frac{1}{1-\delta}\Arrowvert (I-P_l)(L^*-I)(L^*)^{-1}e_m \Arrowvert,\nonumber
\end{eqnarray}
which for fixed $m$ goes to $0$ as $l \rightarrow \infty$.  We conclude $\lim_{l \rightarrow \infty} f_{l,m}^* = f_m^*$, which, upon passing to the Fourier transform, yields $\lim_{l \rightarrow \infty} G_{l,m} = G_m$.
